#!/usr/bin/env bash
# Generate a local .env with random secrets and bootstrap passwords (never committed).
set -euo pipefail
cd "$(dirname "$0")/.."
if [[ -f .env ]]; then echo ".env already exists - delete it to regenerate"; exit 0; fi
rand() { openssl rand -base64 24 | tr -d '/+=' | cut -c1-24; }
DB_PASSWORD="${LIFEBOAT_DB_PASSWORD:-$(rand)}"
cat > .env <<ENV
# Generated by scripts/dev-env.sh - local development only. Do not commit.
POSTGRES_PASSWORD=${DB_PASSWORD}
LIFEBOAT_DATABASE_URL=postgresql+psycopg://lifeboat:${DB_PASSWORD}@localhost:5432/lifeboat
LIFEBOAT_JWT_SECRET=$(openssl rand -base64 48 | tr -d '\n')
LIFEBOAT_BOOTSTRAP_ADMIN_PASSWORD=$(rand)
LIFEBOAT_BOOTSTRAP_OPERATOR_PASSWORD=$(rand)
LIFEBOAT_BOOTSTRAP_APPROVER_PASSWORD=$(rand)
LIFEBOAT_BOOTSTRAP_VIEWER_PASSWORD=$(rand)
GRAFANA_ADMIN_PASSWORD=$(rand)
# Optional: enables the LLM copilot (otherwise a rule-based copilot is used)
# LIFEBOAT_ANTHROPIC_API_KEY=
ENV
chmod 600 .env
echo "wrote .env (passwords for admin/operator/approver/viewer are inside)"
